#!/usr/bin/env bash
# PenKit — Single File Project Bundle
# Extracts complete PenKit project structure
set -e

DEST="${1:-penkit}"
mkdir -p "$DEST"
echo "[*] Extracting PenKit project to: $DEST"

mkdir -p "$DEST"
echo "penkit.py"
base64 -d > "$DEST/penkit.py" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "penkit_keys.py"
base64 -d > "$DEST/penkit_keys.py" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "penkit_recon.py"
base64 -d > "$DEST/penkit_recon.py" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "install_tools.sh"
base64 -d > "$DEST/install_tools.sh" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "IMPLEMENTATION.md"
base64 -d > "$DEST/IMPLEMENTATION.md" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "penkit_bundle.spec"
base64 -d > "$DEST/penkit_bundle.spec" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "INSTALL.md"
base64 -d > "$DEST/INSTALL.md" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "report.html"
base64 -d > "$DEST/report.html" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "webapp_linux_x86_64.spec"
base64 -d > "$DEST/webapp_linux_x86_64.spec" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "README.md"
base64 -d > "$DEST/README.md" << "BASEOF"

BASEOF

mkdir -p "$DEST"
echo "penkit_bundle.sh"
base64 -d > "$DEST/penkit_bundle.sh" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp"
echo "webapp/__init__.py"
base64 -d > "$DEST/webapp/__init__.py" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp"
echo "webapp/utils.py"
base64 -d > "$DEST/webapp/utils.py" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp"
echo "webapp/routes.py"
base64 -d > "$DEST/webapp/routes.py" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp/templates"
echo "webapp/templates/base.html"
base64 -d > "$DEST/webapp/templates/base.html" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp/templates"
echo "webapp/templates/index.html"
base64 -d > "$DEST/webapp/templates/index.html" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp/templates"
echo "webapp/templates/builder.html"
base64 -d > "$DEST/webapp/templates/builder.html" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp/templates"
echo "webapp/templates/recon.html"
base64 -d > "$DEST/webapp/templates/recon.html" << "BASEOF"

BASEOF

mkdir -p "$DEST/webapp/templates"
echo "webapp/templates/keys.html"
base64 -d > "$DEST/webapp/templates/keys.html" << "BASEOF"

BASEOF

echo "[+] Done. Run: cd $DEST && python3 penkit.py"
